/// Finds the maximum value in a slice of integers.
///
/// Returns `Some(max)` if the input slice is not empty, otherwise returns `None`.
///
/// # Panics
///
/// This function does not panic. If the input vector is empty, it will return `None` instead.

fn find_max(numbers: &[i32]) -> Option<i32> {
    // Check if the slice is empty
    if numbers.is_empty() {
        return None;
    }

    // Initialize max_value with the first element of the slice
    let mut max_value = *numbers.first().unwrap();

    // Iterate over the rest of the elements in the slice
    for &num in numbers.iter().skip(1) {
        // If we find a larger value, update max_value
        if num > max_value {
            max_value = num;
        }
    }

    // Return max_value as Option<i32>
    Some(max_value)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_find_max_empty_vector() {
        assert_eq!(find_max(&[]), None);
    }

    #[test]
    fn test_find_max_single_element_vector() {
        assert_eq!(find_max(&[1]), Some(1));
    }

    #[test]
    fn test_find_max_multiple_elements_vector() {
        assert_eq!(find_max(&[3, 5, 1, 9, 2]), Some(9));
    }
}

