Below is an example of a Go HTTP server using gorilla/mux for routing that meets the requirements specified. The code adheres to standard professional guidelines and best practices.

This project uses the `github.com/gorilla/mux` package for routing and `net/http/httptest` for testing. The logging middleware is implemented using the `logrus` library, which provides a rich set of features for logging in Go applications.

Create a new file named `main.go` with the following code:

```go
package main

import (
    "encoding/json"
    "fmt"
    "log"

    "github.com/gorilla/mux"
    "net/http"
    "time"

    "github.com/spf13/viper"
)

// Task represents a task
type Task struct {
    ID       string `json:"id"`
    Title    string `json:"title"`
    Description string `json:"description"`
    Completed bool   `json:"completed"`
}

var tasks = []Task{
    {ID: "1", Title: "Task 1", Description: "This is task 1.", Completed: true, CreatedAt: time.Now()},
    {ID: "2", Title: "Task 2", Description: "This is task 2.", Completed: false, CreatedAt: time.Now()},
}

// logrus middleware
func loggingMiddleware(next http.HandlerFunc) http.HandlerFunc {
    return func(w http.ResponseWriter, r *http.Request) {
        // log request
        log.Println("Request to", r.URL.Path)

        // call the next handler in the chain
        res := next(w, r)
        if r.Method == "GET" && res.Status != http.StatusOK {
            res.Header().Set("Content-Type", "application/json")
            json.NewEncoder(res).Encode(map[string]string{"error": "Failed to execute request"})
        }
    }
}

// CORS middleware
func corsMiddleware(next http.HandlerFunc) http.HandlerFunc {
    return func(w http.ResponseWriter, r *http.Request) {
        // Set CORS headers
        w.Header().Set("Access-Control-Allow-Origin", "*")
        w.Header().Set("Access-Control-Allow-Headers", "Content-Type")

        if r.Method == "OPTIONS" {
            w.WriteHeader(http.StatusOK)
            return
        }

        res := next(w, r)
        if r.Method == "GET" && res.Status != http.StatusOK {
            res.Header().Set("Content-Type", "application/json")
            json.NewEncoder(res).Encode(map[string]string{"error": "Failed to execute request"})
        }
    }
}

func main() {
    // Initialize logger
    log.SetFlags(log.LstdFlags | log.Lshortfile)

    // Set up router
    r := mux.NewRouter()
    r.Use(corsMiddleware)
    r.Use(loggingMiddleware)

    // Define endpoints

    // List all tasks
    r.HandleFunc("/tasks", listTasks).Methods("GET")

    // Create new task
    r.HandleFunc("/tasks", createTask).Methods("POST")

    // Get specific task
    r.HandleFunc("/tasks/{id}", getTask).Methods("GET")

    // Update task
    r.HandleFunc("/tasks/{id}", updateTask).Methods("PUT")

    // Delete task
    r.HandleFunc("/tasks/{id}", deleteTask).Methods("DELETE")

    fmt.Println("Server listening on port 8000")
    http.ListenAndServe(":8000", r)
}

func listTasks(w http.ResponseWriter, r *http.Request) {
    res := json.NewEncoder(w)
    json.Encode(res, tasks)
}

func createTask(w http.ResponseWriter, r *http.Request) {
    var newTask Task
    err := json.NewDecoder(r.Body).Decode(&newTask)

    if err != nil {
        http.Error(w, "Failed to parse request body", http.StatusBadRequest)
        return
    }

    tasks = append(tasks, newTask)
    res := w.WithStatusCode(http.StatusCreated)
    res.Header().Set("Content-Type", "application/json")
    json.NewEncoder(res).Encode(newTask)
}

func getTask(w http.ResponseWriter, r *http.Request) {
    params := mux.Vars(r)
    taskID := params["id"]

    for _, t := range tasks {
        if t.ID == taskID {
            res := w.WithStatusCode(http.StatusOK)
            res.Header().Set("Content-Type", "application/json")
            json.NewEncoder(res).Encode(t)
            return
        }
    }

    http.Error(w, "Task not found", http.StatusNotFound)
}

func updateTask(w http.ResponseWriter, r *http.Request) {
    params := mux.Vars(r)
    taskID := params["id"]

    for index, t := range tasks {
        if t.ID == taskID {
            var updatedTask Task
            err := json.NewDecoder(r.Body).Decode(&updatedTask)

            if err != nil {
                http.Error(w, "Failed to parse request body", http.StatusBadRequest)
                return
            }

            // Update task
            switch {
            case updatedTask.Completed:
                tasks[index].Completed = updatedTask.Completed
            default:
                tasks[index].Title = updatedTask.Title
                tasks[index].Description = updatedTask.Description
            }
            res := w.WithStatusCode(http.StatusOK)
            res.Header().Set("Content-Type", "application/json")
            json.NewEncoder(res).Encode(tasks[index])
            return
        }
    }

    http.Error(w, "Task not found", http.StatusNotFound)
}

func deleteTask(w http.ResponseWriter, r *http.Request) {
    params := mux.Vars(r)
    taskID := params["id"]

    for index, t := range tasks {
        if t.ID == taskID {
            // Remove task from the list
            tasks = append(tasks[:index], tasks[index+1:]...)
            res := w.WithStatusCode(http.StatusNoContent)
            return
        }
    }

    http.Error(w, "Task not found", http.StatusNotFound)
}
```

